// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        bool ok;
        bytes memory ret;
        vm.prank(caller);
        try c.version() returns (string memory s) {
            ok = true;
            ret = bytes(s);
        } catch {
            ok = false;
            ret = "";
        }

        assertTrue(ok && ret.length > 0);
    }
}
